// Local, synthetic audio fixture. No microphone, system capture, or cloud requests.
demoRecord.id='clang-audio-demo';demoRecord.audioSrc='audio/clang-sample.wav';demoRecord.duration=audioTiming.duration;demoRecord.lines.forEach((line,i)=>line.time=audioTiming.starts[i]);
try{const edits=JSON.parse(localStorage.getItem('livecap.demo.edits')||'null');if(edits){if(typeof edits.title==='string')demoRecord.title=edits.title;if(typeof edits.note==='string')demoRecord.note=edits.note;if(Array.isArray(edits.lines)&&edits.lines.length===4)edits.lines.forEach((x,i)=>{if(typeof x.zh==='string'&&typeof x.en==='string'){demoRecord.lines[i].zh=x.zh;demoRecord.lines[i].en=x.en}})}}catch{}
const media={audio:new Audio(),record:null,key:null,url:null,loading:false,error:'',follow:true,rate:1,volume:.8};
media.audio.preload='metadata';media.audio.volume=.8;
const recordChats=new Map();let chatBusy=false;
function recordKey(r){return r.id||r.date+'|'+r.title}
function persistRecord(r){try{if(r===demoRecord)localStorage.setItem('livecap.demo.edits',JSON.stringify({title:r.title,note:r.note,lines:r.lines}));else localStorage.setItem('livecap.client.records',JSON.stringify(state.records));return true}catch{toast('本地空间不足，修改未保存');return false}}
function audioDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('livecap-prototype-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function storeAudio(key,blob){const db=await audioDB();return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(blob,key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function readAudio(key){const db=await audioDB();return new Promise((resolve,reject)=>{const req=db.transaction('audio').objectStore('audio').get(key);req.onsuccess=()=>{db.close();resolve(req.result)};req.onerror=()=>{db.close();reject(req.error)}})}
async function attachAudio(r){const key=recordKey(r);if(media.key===key)return;media.audio.pause();media.audio.removeAttribute('src');media.audio.load();if(media.url)URL.revokeObjectURL(media.url);media.url=null;media.key=key;media.record=r;media.error='';media.loading=true;try{let src=r.audioSrc;if(src){const response=await fetch(src);if(!response.ok)throw Error('audio');const blob=await response.blob();if(media.key!==key)return;media.url=URL.createObjectURL(blob);src=media.url}if(r.audioKey){const blob=await readAudio(r.audioKey);if(media.key!==key)return;if(!blob)throw Error('missing');media.url=URL.createObjectURL(blob);src=media.url}if(media.key!==key)return;if(src){media.audio.src=src;media.audio.playbackRate=media.rate;media.audio.load()}else media.error='这条早期记录没有保存音频'}catch{if(media.key===key)media.error='音频暂时无法读取，请重试'}finally{if(media.key===key){media.loading=false;updatePlayer()}}}
function playerMarkup(r){const has=!!(r.audioSrc||r.audioKey);return `<div class="audio-player"><div class="audio-heading"><span><i class="audio-icon">≋</i> ${has?'会话录音':'音频'}</span><span class="audio-badge">${r.example?'本地合成语音示例':has?'已自动保存':'未保存音频'}</span></div><input id="audio-seek" aria-label="音频播放进度" type="range" min="0" max="${r.duration}" step="0.1" value="0" ${has?'':'disabled'}><div class="audio-controls"><button data-audio-play aria-label="播放录音" ${has?'':'disabled'}>▷</button><button data-audio-mute aria-label="静音">◖</button><input id="audio-volume" aria-label="音量" type="range" min="0" max="1" step="0.05" value="${media.volume}"><span id="audio-clock">00:00 / ${clockText(r.duration)}</span><span class="audio-spacer"></span><button data-audio-follow aria-pressed="${media.follow}">${media.follow?'跟随播放':'自由阅读'}</button><select id="audio-speed" aria-label="播放速度">${[.75,1,1.25,1.5,2].map(x=>`<option value="${x}" ${x===media.rate?'selected':''}>${x}×</option>`).join('')}</select><button data-audio-download aria-label="下载录音" ${has?'':'disabled'}>↓</button></div><div id="audio-error" role="status"></div></div>`}
function updatePlayer(){if(state.page!=='records'||!activeRecord())return;const a=media.audio,r=activeRecord();const seek=document.querySelector('#audio-seek');if(seek){seek.value=a.currentTime||0;seek.style.setProperty('--played',((a.currentTime||0)/(r.duration||1)*100)+'%')}const clock=document.querySelector('#audio-clock');if(clock)clock.textContent=clockText(a.currentTime||0)+' / '+clockText(r.duration);const b=document.querySelector('[data-audio-play]');if(b){b.textContent=a.paused?'▷':'Ⅱ';b.setAttribute('aria-label',a.paused?'播放录音':'暂停录音');b.disabled=media.loading||!!media.error||!(r.audioSrc||r.audioKey)}const mute=document.querySelector('[data-audio-mute]');if(mute){mute.textContent=a.muted?'静音':'◖';mute.setAttribute('aria-label',a.muted?'取消静音':'静音')}const err=document.querySelector('#audio-error');if(err)err.textContent=media.error;let idx=0;r.lines.forEach((x,i)=>{if(x.time<=a.currentTime)idx=i});document.querySelectorAll('.transcript-paragraph').forEach((el,i)=>el.classList.toggle('playing',!a.paused&&i===idx));if(!a.paused&&media.follow&&media.lastParagraph!==idx){media.lastParagraph=idx;document.querySelector('#source-'+idx)?.scrollIntoView({block:'nearest',behavior:'smooth'})}}
media.audio.addEventListener('timeupdate',updatePlayer);media.audio.addEventListener('loadedmetadata',updatePlayer);media.audio.addEventListener('play',updatePlayer);media.audio.addEventListener('pause',updatePlayer);media.audio.addEventListener('ended',updatePlayer);media.audio.addEventListener('error',()=>{if(media.audio.getAttribute('src')){media.error='音频加载失败，请重新打开记录';updatePlayer()}});
function afterRecordRender(){media.lastParagraph=-1;if(state.page==='records'&&activeRecord()){attachAudio(activeRecord());updatePlayer();document.querySelector('#audio-volume')?.setAttribute('value',media.volume)}else{media.audio.pause();media.key=null;media.record=null} }
function seekRecord(i){const r=activeRecord();if(!r?.lines[i]||!media.audio.getAttribute('src'))return;media.audio.currentTime=r.lines[i].time;media.lastParagraph=i;updatePlayer()}
function sessionText(){const t=state.tick;let idx=0;demoRecord.lines.forEach((x,i)=>{if(x.time<=t)idx=i});const line=demoRecord.lines[idx],end=demoRecord.lines[idx+1]?.time||demoRecord.duration;const ratio=state.started||t>0?Math.min(1,(t-line.time+.8)/(end-line.time-.5)):1;const zhUnits=line.zh.match(/[A-Za-z][A-Za-z+\/-]*|./gu)||[];const words=line.en.split(' ');return {zh:zhUnits.slice(0,Math.max(1,Math.floor(zhUnits.length*ratio))).join(''),en:words.slice(0,Math.max(1,Math.floor(words.length*ratio))).join(' '),time:line.time}}
async function autoArchiveSession(){if(state.archiving)return;state.archiving=true;const duration=state.tick;toast('正在保存音频与文字…');render();try{const response=await fetch('audio/clang-sample.wav');if(!response.ok)throw Error();const buffer=await response.arrayBuffer();const view=new DataView(buffer);const bytesPerSecond=view.getUint32(28,true),align=view.getUint16(32,true);const bytes=Math.min(buffer.byteLength-44,Math.max(align,Math.floor(duration*bytesPerSecond/align)*align));const clip=buffer.slice(0,44+bytes);const clipView=new DataView(clip);clipView.setUint32(4,36+bytes,true);clipView.setUint32(40,bytes,true);const id='session-'+Date.now();await storeAudio(id,new Blob([clip],{type:'audio/wav'}));const partial=sessionText(),lines=demoRecord.lines.filter((x,i)=>(demoRecord.lines[i+1]?.time||demoRecord.duration)<=duration).map(x=>({...x}));if(!lines.some(x=>x.time===partial.time))lines.push({...partial,speaker:state.speaker});const r={id,title:'Clang 前端 · 演示会话',date:new Date().toLocaleString('zh-CN'),duration:bytes/bytesPerSecond,lines,audioKey:id,audioBytes:clip.byteLength,summary:'',status:'saved'};state.records.unshift(r);if(!persistRecord(r))return;state.selectedRecord=0;recordUI.tab='minutes';recordUI.selected=-1;state.tick=0;go('records');render();toast('音频与文字已自动保存')}catch{toast('保存失败，可在当前会话重试');state.started=true;render()}finally{state.archiving=false}}
function templateSelector(r){return `<label class="template-control">✧ <select aria-label="纪要模板" id="minutes-template">${[['visual','图文纪要'],['brief','精简摘要'],['outline','议题笔记']].map(([v,l])=>`<option value="${v}" ${recordUI.template===v?'selected':''}>${l}</option>`).join('')}</select></label>`}
recordUI.template='visual';
function recordDocument(r){if(recordUI.tab==='timeline')return recordTimeline(r);if(r.note)return `<div class="edited-note"><span>已编辑</span>${r.note.split('\n').map(x=>x.trim()?`<p>${esc(x)}</p>`:'<br>').join('')}</div>`;if(!r.example)return `<div class="document-empty"><span>✓</span><h2>录音与原文已保存</h2><p>现在可以回听音频、校对原文。</p><button class="primary" data-generate-note>整理片段笔记</button><small>原型会从当前原文整理示例笔记</small></div>`;if(recordUI.tab==='overview'||recordUI.template==='brief')return recordSummary(r);if(recordUI.template==='outline')return `<div class="summary-lead"><h2>议题笔记</h2></div>${r.topics.map(([t,d,i])=>`<section class="minutes-section"><div><h3>${esc(t)}</h3>${sourceButton(i)}</div><p>${esc(d)}</p></section>`).join('')}`;return recordMinutes(r)}
function showEdit(kind,index){const r=activeRecord(),dialog=document.querySelector('#detail');dialog.dataset.editKind=kind;dialog.dataset.editIndex=index??'';let body='';if(kind==='title')body=`<input id="record-title-input" aria-label="记录标题" maxlength="120" value="${esc(r.title)}">`;if(kind==='note')body=`<textarea id="record-note-input" aria-label="纪要内容" rows="14">${esc(r.note||document.querySelector('.document-scroll').innerText)}</textarea>`;if(kind==='line'){const line=r.lines[index];body=`<label>说话人<input id="line-speaker" value="${esc(line.speaker||'说话人 1')}" aria-label="段落说话人"></label><label>原文<textarea id="line-original" aria-label="编辑原文" rows="5">${esc(line.en)}</textarea></label><label>译文<textarea id="line-translation" aria-label="编辑译文" rows="5">${esc(line.zh)}</textarea></label>`}dialog.innerHTML=`<div class="dialog-top"><h2>${{title:'修改标题',note:'编辑纪要',line:'校对转录'}[kind]}</h2></div>${body}<div class="dialog-actions"><button data-action="close-dialog">取消</button><button class="primary" data-save-record-edit>保存修改</button></div>`;dialog.showModal()}
function saveEdit(){const r=activeRecord(),dialog=document.querySelector('#detail'),kind=dialog.dataset.editKind;if(kind==='title'){const value=document.querySelector('#record-title-input').value.trim();if(!value)return;r.title=value}if(kind==='note')r.note=document.querySelector('#record-note-input').value;if(kind==='line'){const line=r.lines[Number(dialog.dataset.editIndex)];line.speaker=document.querySelector('#line-speaker').value.trim()||'说话人 1';line.en=document.querySelector('#line-original').value.trim();line.zh=document.querySelector('#line-translation').value.trim()}if(persistRecord(r)){dialog.close();render();toast('修改已保存')}}
function questionMarkup(r){const chat=recordChats.get(recordKey(r))||[];return `<div class="record-assistant"><div class="assistant-heading"><span>✧ 问这条记录</span><small>本地示例问答</small></div>${chat.length?`<div class="answer-thread">${chat.slice(-2).map(c=>`<div class="question-bubble">${esc(c.q)}</div><div class="answer-bubble">${esc(c.answer)}<div>${c.refs.map(i=>sourceButton(i)).join(' ')}</div></div>`).join('')}</div>`:''}<div class="question-prompts">${['提炼重点','解释 Sema','有哪些待办？'].map(q=>`<button data-question="${q}">${q}</button>`).join('')}</div><form id="record-question-form"><input aria-label="询问这条记录" id="record-question-input" placeholder="这段内容中，你想了解什么？" autocomplete="off"><button type="submit" aria-label="发送问题" ${chatBusy?'disabled':''}>↑</button></form></div>`}
function askRecord(q){q=q.trim();if(!q)return;const r=activeRecord();let answer='',refs=[];if(/待办|任务|todo/i.test(q)){answer='这份记录中没有明确的负责人或截止时间，不能据此生成已确认的待办。';if(r.example){answer+='讲者仅提到后续课程将展开优化算法。';refs=[3]}}else if(/重点|总结|summary/.test(q)&&r.summary){answer=r.summary;refs=r.lines.map((_,i)=>i)}else{const tokens=q.toLowerCase().match(/[a-z]{2,}|[\u4e00-\u9fff]{2,}/g)||[];if(/语义|sema/i.test(q))tokens.push('sema','semantic');if(/解析|parser/i.test(q))tokens.push('parser');const scores=r.lines.map((line,i)=>({i,score:tokens.reduce((n,t)=>n+(line.en.toLowerCase().split(/[^a-z]+/).includes(t)?4:(line.zh+' '+line.en).toLowerCase().includes(t)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);refs=scores.slice(0,2).map(x=>x.i);answer=refs.length?'原文中相关的表述是：\n'+refs.map(i=>r.lines[i].zh).join('\n\n'):'当前记录中没有找到可支持这个问题的片段。可以试试具体术语或“提炼重点”。'}const key=recordKey(r),chat=recordChats.get(key)||[];chat.push({q,answer,refs});recordChats.set(key,chat);render()}
function workspaceClick(b){const d=b.dataset;if(usageClick(b))return true;if(d.audioPlay!==undefined){if(media.audio.paused)media.audio.play().catch(()=>{media.error='播放未成功，请重试';updatePlayer()});else media.audio.pause();return true}if(d.audioMute!==undefined){media.audio.muted=!media.audio.muted;b.textContent=media.audio.muted?'静音':'◖';b.setAttribute('aria-label',media.audio.muted?'取消静音':'静音');return true}if(d.audioFollow!==undefined){media.follow=!media.follow;render();return true}if(d.audioDownload!==undefined){if(media.audio.src){const a=document.createElement('a');a.href=media.audio.src;a.download=activeRecord().title+'.wav';a.click()}return true}if(d.editTitle!==undefined){showEdit('title');return true}if(d.editMinutes!==undefined){showEdit('note');return true}if(d.editLine!==undefined){showEdit('line',Number(d.editLine));return true}if(d.saveRecordEdit!==undefined){saveEdit();return true}if(d.question){askRecord(d.question);return true}if(d.generateNote!==undefined){const r=activeRecord();r.note='片段笔记\n\n'+r.lines.map(x=>clockText(x.time)+' '+x.zh).join('\n\n');persistRecord(r);render();return true}return coreWorkspaceClick(b)}
document.addEventListener('input',e=>{if(e.target.id==='audio-seek'){media.audio.currentTime=Number(e.target.value);updatePlayer()}if(e.target.id==='audio-volume'){media.volume=Number(e.target.value);media.audio.volume=media.volume;media.audio.muted=false;updatePlayer()}});
document.addEventListener('change',e=>{if(e.target.id==='audio-speed'){media.rate=Number(e.target.value);media.audio.playbackRate=media.rate}if(e.target.id==='minutes-template'){recordUI.template=e.target.value;recordUI.tab='minutes';render()}});
document.addEventListener('submit',e=>{if(e.target.id==='record-question-form'){e.preventDefault();askRecord(document.querySelector('#record-question-input').value)}});
const usageUI={days:7,metric:'cost',day:null,expanded:null,sort:'date'};
const usageFixtures=[['Clang 前端职责与数据流',0,24,[18,7,3,1]],['设计系统评审',0,42,[31,12,5,0]],['LLVM IR 与优化',1,36,[27,10,4,2]],['产品策略讨论',2,28,[21,8,3,0]],['编译器课程笔记',3,58,[44,16,6,2]],['开发者播客',4,47,[35,13,4,0]],['项目周会',6,31,[23,9,4,0]],['类型系统分享',8,40,[30,11,5,3]],['用户研究访谈',11,52,[39,15,6,0]],['AST 构建方案研讨',15,38,[29,11,4,2]],['前端工程讨论',20,26,[20,7,3,0]],['技术课程',25,64,[48,18,7,2]]].map(([title,age,minutes,parts],id)=>({title,age,minutes,parts,id,cost:parts.reduce((a,b)=>a+b,0)}));
const costNames=['语音转录','字幕翻译','总结与纪要','知识整理'],costColors=['#738c61','#9caf88','#b4a3c7','#dbb892'];
function dollars(cents){return '$'+(cents/100).toFixed(2)}
function usageDate(age){const d=new Date(2026,10,7-age);return `${d.getMonth()+1}/${String(d.getDate()).padStart(2,'0')}`}
function usagePage(){const events=usageFixtures.filter(r=>r.age<usageUI.days),parts=costNames.map((_,i)=>events.reduce((n,r)=>n+r.parts[i],0)),total=parts.reduce((a,b)=>a+b,0),minutes=events.reduce((n,r)=>n+r.minutes,0);const daily=Array.from({length:usageUI.days},(_,j)=>{const age=usageUI.days-1-j,rs=events.filter(r=>r.age===age);return {age,cost:rs.reduce((n,r)=>n+r.cost,0),minutes:rs.reduce((n,r)=>n+r.minutes,0)}}),max=Math.max(1,...daily.map(x=>x[usageUI.metric]));let accumulated=0;const gradient=parts.map((v,i)=>{const start=accumulated;accumulated+=v/total*100;return `${costColors[i]} ${start}% ${accumulated}%`}).join(',');const rows=events.filter(r=>usageUI.day===null||r.age===usageUI.day).sort((a,b)=>usageUI.sort==='cost'?b.cost-a.cost:a.age-b.age);return `<div class="usage-dashboard"><div class="usage-page-heading"><div><h1>用量</h1><p>每一次聆听，花费一目了然。</p></div><div><span class="sample-chip">示例账单</span><div class="segmented">${[7,30].map(n=>`<button data-usage-days="${n}" class="${usageUI.days===n?'active':''}">近 ${n} 天</button>`).join('')}</div></div></div><div class="usage-hero"><div class="usage-total"><span>累计费用 <small>USD</small></span><strong>${dollars(total)}</strong><p>${usageDate(usageUI.days-1)} — ${usageDate(0)}</p></div><div><span>转录时长</span><strong>${Math.floor(minutes/60)}<small>小时</small> ${minutes%60}<small>分</small></strong></div><div><span>处理记录</span><strong>${events.length}<small>条</small></strong></div><div><span>平均每条</span><strong>${dollars(total/events.length)}</strong></div></div><div class="usage-charts"><section class="trend-card"><header><h3>使用趋势</h3><div class="segmented"><button data-usage-metric="cost" class="${usageUI.metric==='cost'?'active':''}">费用</button><button data-usage-metric="minutes" class="${usageUI.metric==='minutes'?'active':''}">时长</button></div></header><div class="chart-unit">${usageUI.metric==='cost'?'USD':'分钟'} · 点击柱形查看当天记录</div><div class="bar-chart" role="group" aria-label="按日用量">${daily.map((d,i)=>`<button data-usage-day="${d.age}" class="${usageUI.day===d.age?'selected':''}" aria-label="${usageDate(d.age)} ${usageUI.metric==='cost'?dollars(d.cost):d.minutes+'分钟'}" title="${usageDate(d.age)} · ${dollars(d.cost)} · ${d.minutes} 分钟"><span class="bar-value">${usageUI.metric==='cost'?dollars(d.cost):d.minutes}</span><span class="chart-bar" style="height:${d[usageUI.metric]/max*132+3}px"></span><small>${usageUI.days===7||i%5===0||i===29?usageDate(d.age):''}</small></button>`).join('')}</div></section><section class="breakdown-card"><h3>费用构成</h3><div class="cost-donut" role="img" aria-label="${parts.map((v,i)=>costNames[i]+' '+dollars(v)).join('，')}" style="background:conic-gradient(${gradient})"><span><small>总费用</small><strong>${dollars(total)}</strong></span></div><div class="cost-legend">${parts.map((v,i)=>`<div><i style="background:${costColors[i]}"></i><span>${costNames[i]}</span><b>${dollars(v)}</b><small>${Math.round(v/total*100)}%</small></div>`).join('')}</div></section></div><section class="record-costs"><header><div><h3>按记录查看费用</h3><p>${usageUI.day===null?'费用归入对应会话，展开查看各项明细':usageDate(usageUI.day)+' · 当日记录'}</p></div><div>${usageUI.day!==null?'<button class="ghost small" data-usage-reset>显示全部</button>':''}<button class="small" data-usage-sort>${usageUI.sort==='date'?'按时间 ↓':'按费用 ↓'}</button></div></header><div class="cost-table"><div class="cost-table-head"><span>记录</span><span>日期</span><span>时长</span><span>费用</span></div>${rows.map(r=>`<button class="cost-row" data-usage-row="${r.id}" aria-expanded="${usageUI.expanded===r.id}"><span><i>▤</i>${esc(r.title)}</span><span>${usageDate(r.age)}</span><span>${r.minutes} 分钟</span><strong>${dollars(r.cost)} <small>${usageUI.expanded===r.id?'⌃':'⌄'}</small></strong></button>${usageUI.expanded===r.id?`<div class="cost-row-detail">${r.parts.map((v,i)=>`<div><span><i style="background:${costColors[i]}"></i>${costNames[i]}</span><strong>${dollars(v)}</strong></div>`).join('')}</div>`:''}`).join('')||'<div class="records-empty">当天没有记录费用</div>'}</div></section><p class="usage-footnote">当前为交互设计示例；金额用于演示费用归属，不代表服务商报价或实际账单。</p></div>`}
function usageClick(b){const d=b.dataset;if(d.usageDays){usageUI.days=Number(d.usageDays);usageUI.day=null;usageUI.expanded=null;render();return true}if(d.usageMetric){usageUI.metric=d.usageMetric;render();return true}if(d.usageDay!==undefined){usageUI.day=usageUI.day===Number(d.usageDay)?null:Number(d.usageDay);usageUI.expanded=null;render();return true}if(d.usageRow!==undefined){usageUI.expanded=usageUI.expanded===Number(d.usageRow)?null:Number(d.usageRow);render();return true}if(d.usageReset!==undefined){usageUI.day=null;render();return true}if(d.usageSort!==undefined){usageUI.sort=usageUI.sort==='date'?'cost':'date';render();return true}return false}
